fn calculate_jungle_action_score(_rnd, player, data, _parameter, _action, effect, t) -> i64

// L522
team = player.info.team              // PlayerState+0x930, team>=2 면 panic_bounds_check(bound=2)
pos  = player.info.position.as_index()  // PlayerState+0x9c0, range [0,5) — as_index 인라인(entity.rs:580)
champ = data.cache.player_champion[team][pos]   // AbstractGameWithCache+0x1e0, [[Option<&Entity>;5];2]
if champ is None { panic }           // Option::unwrap 인라인(option.rs:1010). 분기예측 메타 !prof 는 None 을 2000:1 로 비정상 취급

// L523 — champ 은 (데이터포인터, Entity의 AbstractEntity vtable) 팻포인터로 쪼개져 전달됨
value = effect.expected_damage_target(data.context, champ as &dyn AbstractEntity, t)   // i64

// L524
hp = t.hp                            // Entity+0x670

// L526~536 — 소스는 else-if 체인이지만 LLVM 에선 t.ty 판별자(Entity+0x68) 하나에 대한 switch 로 접힘
// (is_nexus/is_tower/is_jungle/is_minion 전부 인라인되어 사라짐)
coef = match t.ty.tag {
  3 /*Nexus*/  => 200,                        // L526 is_nexus() (entity.rs:1399)
  2 /*Tower*/  => 80,                         // L528 is_tower()
  4 /*Jungle*/ => {                           // L530 is_jungle() (entity.rs:1377)
      camp_team = t.ty.Jungle.info.camp_type.0 // Entity+0x98
      if camp_team < 2 {                       // is_jungle() 의 실제 술어
          if hp > value { 20 } else { 40 }     // L531 — icmp sgt %hp,%value ? 20 : 40
      } else { 0 }                             // is_jungle()==false → 아래 else 로 흘러 0
  },
  1 /*Minion*/ => -10,                        // L536
  _            => 0,                          // L536 (None/Epic/Serpen/Ghoul/SmallJiangshi/Bear/Eagle/Revenant/Illusion/Champion)
}

// L542 — is_jungle() 를 한 번 더 인라인 평가(같은 두 로드)
based = if t.ty.tag == 4 && t.ty.Jungle.info.camp_type.0 < 2 { 5 } else { 0 }

// L548 — 여기서 hp==0 이면 panic_const_div_by_zero, (coef*value)==i64::MIN && hp==-1 이면 div_overflow
return min(coef * value / hp, coef) + based    // llvm.smin(i64), sdiv(부호 있는 나눗셈)
// dbg 상 self=(coef*value/hp), other=coef 이므로 소스 표기는 (coef * value / hp).min(coef) + based

// 요약: 계수 coef 가 '이 대상 종류의 점수 상한'이자 '피해 효율의 배율' 두 역할을 겸한다.
// 예상피해가 대상 HP 이상이면 coef*value/hp >= coef 라 상한 coef 로 잘리고,
// HP 가 클수록 점수가 선형으로 깎인다. 정글캠프만 +5 의 고정 가산을 받는다.
